import React, { useState, useEffect } from 'react';
import api from '../api'; // Import Axios instance

const FamilyList = ({ tripId, setTrip }) => {
  const [head, setHead] = useState('');
  const [memberCount, setMemberCount] = useState(0);
  const [memberNames, setMemberNames] = useState([]);
  const [families, setFamilies] = useState([]);

  // Fetch families on component mount
  useEffect(() => {
    const fetchFamilies = async () => {
      try {
        const response = await api.get(`/trips/${tripId}/families`);
        setFamilies(response.data.families || []);
      } catch (error) {
        console.error('Error fetching families:', error);
      }
    };

    if (tripId) {
      fetchFamilies();
    }
  }, [tripId]);

  // Add family to the trip
  const handleAddFamily = async () => {
    if (!head || memberCount <= 0 || memberNames.includes('')) return;

    const newFamily = {
      head,
      members: memberNames,
    };

    try {
      const response = await api.post(`/trips/${tripId}/families`, newFamily);
      setFamilies((prevFamilies) => [...prevFamilies, response.data]);
      setTrip((prev) => ({
        ...prev,
        families: [...(prev.families || []), response.data],
      }));

      // Reset inputs
      setHead('');
      setMemberCount(0);
      setMemberNames([]);
    } catch (error) {
      console.error('Error adding family:', error);
    }
  };

  const handleMemberNameChange = (index, value) => {
    const updatedNames = [...memberNames];
    updatedNames[index] = value;
    setMemberNames(updatedNames);
  };

  const handleMemberCountChange = (value) => {
    const count = parseInt(value, 10);
    if (isNaN(count) || count < 0) return;

    setMemberCount(count);
    setMemberNames(new Array(count).fill(''));
  };

  const styles = {
    container: { marginBottom: '20px', padding: '10px', border: '1px solid #ccc', borderRadius: '8px' },
    input: { margin: '5px 10px 5px 0', padding: '5px' },
    button: { padding: '6px 12px', backgroundColor: '#28a745', color: '#fff', border: 'none', borderRadius: '4px' },
    memberInput: { marginBottom: '5px' },
    familyBox: { marginTop: '10px', padding: '5px', backgroundColor: '#f9f9f9', borderRadius: '4px' }
  };

  return (
    <div style={styles.container}>
      <h3>Add Family</h3>

      <input
        type="text"
        placeholder="Family Head"
        value={head}
        onChange={(e) => setHead(e.target.value)}
        style={styles.input}
      />

      <input
        type="number"
        placeholder="Number of Members"
        value={memberCount || ''}
        onChange={(e) => handleMemberCountChange(e.target.value)}
        style={styles.input}
      />

      {memberNames.map((name, index) => (
        <div key={index}>
          <input
            type="text"
            placeholder={`Member ${index + 1} Name`}
            value={name}
            onChange={(e) => handleMemberNameChange(index, e.target.value)}
            style={{ ...styles.input, ...styles.memberInput }}
          />
        </div>
      ))}

      <button onClick={handleAddFamily} style={styles.button}>Add Family</button>

      <h4>Family List:</h4>
      {families.map((family, index) => (
        <div key={index} style={styles.familyBox}>
          <strong>Head:</strong> {family.head}<br />
          <strong>Members:</strong> {family.members.join(', ') || 'None'}
        </div>
      ))}
    </div>
  );
};

export default FamilyList;
